#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Does every `thetowersdk/...` specifier in this repo actually resolve to a file?
 *
 * `check-sdk-imports.mjs` answers a different question — whether the SYMBOLS a file imports exist
 * somewhere in the package — and says so in its own docblock: it is deliberately loose about which
 * entry point they come from, so it cannot follow a barrel it failed to trace.
 *
 * That looseness left a hole exactly the size of this bug. Moving `mechanics/unity-random.ts` into
 * `mechanics/primitives/` kept every symbol exported and every type-check green, while
 * `thetowersdk/internal/mechanics/unity-random` stopped resolving — and the app 500'd on every
 * route until someone opened it. Symbols existing and paths resolving are two claims, and the
 * second one had nothing checking it.
 *
 * So this resolves the specifier the way Node does, through the `exports` map, against the SOURCE
 * tree — because vite aliases `thetowersdk` to `src`, and a check against `dist` reports on the
 * last time somebody ran a build.
 *
 *   node scripts/check-sdk-specifiers.mjs
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const MONOREPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..')

const SKIP = new Set(['node_modules', 'dist', '.git', '.svelte-kit', 'build', 'dumps', 'coverage'])

function walk(dir, out = []) {
  if (!existsSync(dir)) return out
  for (const entry of readdirSync(dir)) {
    if (SKIP.has(entry)) continue
    const full = path.join(dir, entry)
    if (statSync(full).isDirectory()) walk(full, out)
    else if (/\.(ts|tsx|vue|mjs)$/.test(full)) out.push(full)
  }
  return out
}

const exportsMap = JSON.parse(readFileSync(path.join(PACKAGE_ROOT, 'package.json'), 'utf8')).exports

const pick = entry => (typeof entry === 'string' ? entry : (entry.require ?? entry.default ?? entry.import))

/**
 * The source file a `thetowersdk/...` specifier names.
 *
 * The exports map points at `dist`, so its target is translated back to `src` and tried with the
 * extensions TypeScript would use. A subpath that matches no pattern at all is reported too — that
 * is a specifier naming an entry point the package does not publish.
 */
function resolveToSource(specifier) {
  const sub = specifier === 'thetowersdk' ? '.' : `./${specifier.slice('thetowersdk/'.length)}`

  let target = exportsMap[sub] ? pick(exportsMap[sub]) : null
  if (!target) {
    for (const [key, entry] of Object.entries(exportsMap)) {
      if (!key.includes('*')) continue
      const [before, after] = key.split('*')
      if (!sub.startsWith(before) || !sub.endsWith(after)) continue
      const star = sub.slice(before.length, sub.length - (after.length || 0))
      target = pick(entry).replace('*', star)
      break
    }
  }
  if (!target) return { ok: false, why: 'no entry point matches' }

  const asSource = target.replace(/^\.\/dist\//, 'src/').replace(/\.js$/, '')
  const raw = target.replace(/^\.\//, '')

  /*
   * ONE candidate, because the exports map yields ONE file.
   *
   * This used to also try `<asSource>/index.ts`, which made every directory look resolvable:
   * `thetowersdk/internal/formatting/numbers` matched `src/formatting/numbers/index.ts` and was
   * reported fine. Node does not do that. `./internal/*` maps to `./dist/*.js`, so the specifier
   * asks for `dist/formatting/numbers.js` -- a file that does not exist next to the directory
   * `dist/formatting/numbers/`. There is no directory-index fallback inside an exports target.
   *
   * The leniency hid four real breakages introduced by turning single modules into folders, and
   * they only surfaced in the platform BUILD, which resolves through `dist` for real. A checker
   * that resolves more loosely than the runtime is not checking the thing that breaks.
   */
  const candidates = [`${asSource}.ts`, `${asSource}.json`]

  /*
   * `mcp/` and the fixtures ship as-is rather than being built, so their targets are checked
   * where they actually live. Anything under `dist/` is NOT — that directory holds the output of
   * the last build, and consulting it lets a stale artifact vouch for a module that has moved.
   *
   * The first version of this check did consult it, and reported
   * `thetowersdk/internal/mechanics/unity-random` as resolving while the app was 500ing on it.
   * A checker that reads build output is answering a question about the past.
   */
  if (!raw.startsWith('dist/')) candidates.push(raw)
  const found = candidates.find(candidate => existsSync(path.join(PACKAGE_ROOT, candidate)))
  return found ? { ok: true } : { ok: false, why: `nothing at ${asSource}` }
}

const SPEC = /['"](thetowersdk(?:\/[A-Za-z0-9_./-]+)?)['"]/g

function main() {
  const files = [
    ...walk(path.join(PACKAGE_ROOT, 'src')),
    ...walk(path.join(PACKAGE_ROOT, 'tests')),
    ...walk(path.join(PACKAGE_ROOT, 'scripts')),
    ...walk(path.join(PACKAGE_ROOT, 'tooling')),
    ...walk(path.join(PACKAGE_ROOT, 'mcp')),
    ...walk(path.join(MONOREPO_ROOT, 'packages', 'platform', 'src')),
    ...walk(path.join(MONOREPO_ROOT, 'src')),
  ]

  const broken = new Map()
  let checked = 0

  for (const file of files) {
    const text = readFileSync(file, 'utf8')
    if (!text.includes('thetowersdk')) continue
    for (const match of text.matchAll(SPEC)) {
      const specifier = match[1]
      /*
       * Prose quotes example specifiers, so only statements count — and a docblock explaining
       * `import { a, b } from 'thetowersdk/x'` reads exactly like a statement to the check above.
       * The line's own leading characters settle it: a comment cannot be an import.
       */
      const lineStart = text.lastIndexOf('\n', match.index) + 1
      const line = text.slice(lineStart, text.indexOf('\n', match.index))
      if (/^\s*(\*|\/\/|\/\*)/.test(line)) continue

      const before = text.slice(Math.max(0, match.index - 80), match.index)
      if (!/\b(from|import|require)\s*\(?\s*$/.test(before)) continue
      checked += 1
      const result = resolveToSource(specifier)
      if (result.ok) continue
      if (!broken.has(specifier)) broken.set(specifier, { why: result.why, where: new Set() })
      broken.get(specifier).where.add(path.relative(MONOREPO_ROOT, file).split(path.sep).join('/'))
    }
  }

  console.log(`Checked ${checked} thetowersdk specifiers across ${files.length} files.`)

  if (broken.size === 0) {
    console.log('Every one resolves to a source file.')
    return
  }

  console.log(`\n${broken.size} do NOT resolve:\n`)
  for (const [specifier, { why, where }] of [...broken].sort()) {
    console.log(`  ${specifier}  — ${why}`)
    for (const file of [...where].sort().slice(0, 4)) console.log(`      ${file}`)
    if (where.size > 4) console.log(`      … and ${where.size - 4} more`)
  }
  console.log('\nA moved module has to reach the specifiers that name it, not just keep its exports.')
  process.exitCode = 1
}

main()
